from pathlib import Path

from poke_env.battle import PokemonType
from poke_env.data import GenData


def generate_python_type_chart(chart: dict[str, dict[str, float]], types: list[str]):
    type_name_lines = "\n".join(f'    {name} = "{name}"' for name in types)
    multiplier_lines = "\n".join(
        f"    ({', '.join(f'{float(chart.get(defender, {}).get(move, 1)):.1f}' for move in types)}), # {defender}"
        for defender in types
    )

    output = Path(__file__).parent.parent / "src" / "agent" / "engine" / "type_chart.py"
    output.write_text(
        "# generated by scripts/generate_type_chart.py\n"
        "# TYPE_CHART[defender_type][move_type] -> damage multiplier\n"
        "from enum import StrEnum\n\n\n"
        f"class Type(StrEnum):\n{type_name_lines}\n\n\n"
        "# fmt: off\n"
        f"TYPE_CHART: tuple[tuple[float, ...], ...] = (\n{multiplier_lines}\n)\n"
        "# fmt: on\n\n\n"
        "_TYPE_INDEX = {pokemon_type: index for index, pokemon_type in enumerate(Type)}\n\n\n"
        "def get_type_multiplier(defender_type: Type, move_type: Type) -> float:\n"
        "    return TYPE_CHART[_TYPE_INDEX[defender_type]][_TYPE_INDEX[move_type]]\n"
    )


def generate_rust_type_chart(chart: dict[str, dict[str, float]], types: list[str]):
    type_name_lines = "\n".join(f"    {to_pascal_case(name)}," for name in types)
    multiplier_lines = "\n".join(
        f"    [{', '.join(f'{float(chart.get(defender, {}).get(move, 1)):.1f}' for move in types)}], // {defender}"
        for defender in types
    )

    output = Path(__file__).parent.parent / "src" / "type_chart.rs"
    output.write_text(
        "// generated by scripts/generate_type_chart.py\n"
        "// TYPE_CHART[defender_type][move_type] -> damage multiplier\n"
        "use serde::Deserialize;\n\n"
        "#[derive(Clone, Copy, Debug, PartialEq, Eq, Deserialize)]\n"
        '#[serde(rename_all = "SCREAMING_SNAKE_CASE")]\n'
        "#[repr(u8)]\n"
        f"pub enum Type {{\n{type_name_lines}\n}}\n\n"
        "#[rustfmt::skip]\n"
        f"pub const TYPE_CHART: [[f64; {len(types)}]; {len(types)}] = [\n{multiplier_lines}\n];\n\n"
        "pub fn get_type_multiplier(defender_type: Type, move_type: Type) -> f64 {\n"
        "    TYPE_CHART[defender_type as usize][move_type as usize]\n"
        "}\n"
    )


def to_pascal_case(name: str) -> str:
    return "".join(word.capitalize() for word in name.split("_"))


if __name__ == "__main__":
    chart = GenData(9).type_chart
    types = [pokemon_type.name for pokemon_type in PokemonType]
    generate_python_type_chart(chart, types)
    generate_rust_type_chart(chart, types)
